from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
import json
from pathlib import Path
v=json.loads((Path(__file__).resolve().parents[1]/'risultati/P03/valori.json').read_text())
f=lambda z:f'{z:.2f}'.replace('.',',')
m=Modulo('P03','Il Nilo: livelli e dipendenza temporale','Volumi annuali, contrasto fra periodi e covarianza HAC')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P03',i,b)
m.sezione_nuova('Serie storica e contrasto dichiarato')
p('Una differenza nella serie storica di Aswan',
'''Il progetto confronta i volumi annuali del Nilo ad Aswan nei periodi 1871–1897 e 1898–1970, utilizzando la serie Nile distribuita con R. La documentazione segnala già un cambiamento prossimo al 1898, che viene quindi assunto come riferimento di una rianalisi. L’argomento riguarda la grandezza del contrasto e la sensibilità della sua incertezza alla dipendenza temporale. La posizione della soglia, essendo nota attraverso la stessa storia della serie, richiede cautela nel descrivere l’analisi come verifica indipendente di un cambiamento.''',tikz=d('D01',linea(.5,2.5,6.9,2.5)+linea(2.7,1.4,2.7,3.5,'Quantum')+n(1.45,1.5,'27 anni',w=2,size=13)+n(4.8,1.5,'73 anni',w=3,size=13)+n(1.45,3.5,'1871–1897',w=2.5,size=11.5)+n(4.8,3.5,'1898–1970',w=3,size=11.5)+n(3.7,5.3,'Separazione ripresa dalla documentazione storica',w=6.7)),richiamo='L’origine della soglia appartiene al protocollo dell’analisi e ne delimita la forza inferenziale.',fonti='R datasets: Nile; Cobb, 1978',origine='P03:1–3,6')
p('Il volume annuale conserva il proprio denominatore',
'''Ogni valore misura un volume accumulato nell’anno, espresso in centinaia di milioni di metri cubi. La portata media richiederebbe invece di dividere quel volume per la durata effettiva dell’anno in secondi, mentre una portata istantanea richiederebbe una risoluzione osservativa differente. Questa distinzione determina unità e interpretazione della differenza fra periodi. Un valore numerico può apparire plausibile anche quando viene associato all’unità sbagliata, per cui il controllo del dizionario precede la scelta del modello.''',formula=r'V_t=10^8y_t\ \mathrm{m^3},\qquad \overline Q_t=\frac{V_t}{\Delta t_t}\ \mathrm{m^3/s}',tikz=d('D02',rect(.5,.6,6.9,2)+n(3.7,1.3,'Volume integrato in un anno',w=6)+a(3.7,2.2,3.7,3.1)+n(5.2,2.65,'÷ secondi',w=2.6,size=11.5)+rect(.5,3.3,6.9,4.7,'Quantum')+n(3.7,4,'Portata media dello stesso anno',w=6)+n(3.7,5.6,'La conversione cambia la scala, non recupera la dinamica interna.',w=6.7,size=11)),richiamo='La scala temporale della misura deve comparire nell’unità e nella conclusione.',origine='P03:4,22')
c=estratto('P03','audit',"d <- read.csv('dati/progetti/nile.csv')\nstopifnot(nrow(d)==100,\n !anyDuplicated(d$year),\n all(diff(d$year)==1),\n range(d$year)==c(1871,1970))\nd$post <- as.integer(d$year>=1898)\ntable(d$post)\ntapply(d$volume_1e8_m3,d$post,mean)")
p('Controllare la continuità degli anni',
'''La tabella contiene cento anni consecutivi e viene confrontata numericamente con il dataset originale di R. Il controllo di unicità e ordinamento distingue una serie regolare da una sequenza con lacune, per la quale il numero di righe non sarebbe sufficiente. L’indicatore post assume valore uno dal 1898 e conserva ventisette osservazioni iniziali e settantatré successive. Questo conteggio rende verificabili i denominatori delle due medie e la composizione del contrasto, prima che il software produca coefficienti e intervalli.''',codice=c,richiamo='L’ordine temporale e la composizione dei periodi vengono verificati sul dato importato.',origine='P03:5,10')
p('La rappresentazione conserva l’ordine temporale',
'''La linea unisce anni consecutivi e mostra la variabilità attorno ai due livelli medi, rappresentati dai segmenti viola. La separazione dichiarata compare insieme alle fluttuazioni che rimangono entro ciascun periodo. In questo modo, un confronto fra medie resta collegato alla storia osservata e alle possibili strutture residue. Il grafico non identifica il momento di un intervento causale né dimostra che ogni anno successivo appartenga a un regime fisico omogeneo; fornisce la descrizione sulla quale verrà costruito il modello semplificato.''',figura='P03/F01',didascalia='Cento volumi annuali. Segmenti viola: medie dei due periodi; linea verticale: soglia dichiarata del 1898.',richiamo='La serie temporale consente di valutare quanto una sintesi per periodi ometta della dinamica osservata.',origine='P03:7')
p('Distribuzioni marginali e diversa durata dei periodi',
'''Le distribuzioni per periodo riassumono posizione e dispersione dei volumi, conservando i punti individuali per mostrare le differenti numerosità. La separazione delle medie si accompagna a una sovrapposizione di valori, che impedisce di interpretare il contrasto come distinzione perfetta fra tutti gli anni. Il grafico marginale integra la serie temporale, dalla quale dipende l’esame dell’ordine e della persistenza. Le due rappresentazioni rispondono pertanto a esigenze complementari della descrizione, pur utilizzando gli stessi cento dati.''',figura='P03/F02',didascalia='Boxplot e osservazioni individuali. La dispersione orizzontale dei punti è soltanto grafica, con seme fissato.',richiamo='Il confronto delle distribuzioni conserva le numerosità e viene letto insieme all’ordine temporale.',origine='P03:8')
m.sezione_nuova('Modello del livello e residui')
p('La regressione codifica una differenza fra medie',
'''Il modello comprende un’intercetta e l’indicatore del secondo periodo. Per un anno iniziale, il valore atteso è l’intercetta; per un anno successivo è la somma dei due coefficienti. La pendenza dell’indicatore coincide quindi con la differenza fra medie, mentre il termine residuo raccoglie gli scostamenti annuali. La specificazione assume un livello costante entro ciascun periodo. Eventuali tendenze interne o altre variazioni sistematiche della media richiederebbero una formulazione ulteriore, che una correzione della covarianza non introduce.''',formula=r'Y_t=\alpha+\beta D_t+\varepsilon_t,\qquad D_t=\mathbf1\{t\geq1898\}\\\widehat\beta=\overline Y_{1898:1970}-\overline Y_{1871:1897}',destra='L’equivalenza algebrica viene controllata nel codice confrontando il coefficiente restituito da lm con la differenza calcolata direttamente. Il controllo verifica l’implementazione del contrasto; l’adeguatezza del modello richiede invece l’esame della serie e dei residui.',richiamo='Il significato di un coefficiente dipende dalla codifica del modello e dall’unità della risposta.',origine='P03:9–10')
p('Grandezza assoluta e variazione relativa',
f'''Le medie dei due periodi sono rispettivamente {f(v['medie'][0])} e {f(v['medie'][1])}, nella scala di centinaia di milioni di metri cubi. La differenza stimata è {f(v['beta'])}, pari a una variazione del {f(v['percentuale'])}% rispetto alla media iniziale. Il denominatore della percentuale viene dichiarato perché un confronto rispetto alla media successiva produrrebbe un valore diverso. Queste quantità descrivono la serie disponibile; la loro interpretazione probabilistica dipende dalle ipotesi sui processi annuali e dalla costruzione del riferimento inferenziale.''',formula=r'\widehat r=100\frac{\widehat\beta}{\overline Y_{1871:1897}}',tikz=d('D03',rect(.6,.8,6.8,2.2)+n(3.7,1.5,'Contrasto assoluto: '+f(v['beta']),w=5.8,size=14)+a(3.7,2.4,3.7,3.2)+rect(.6,3.4,6.8,4.8,'Quantum')+n(3.7,4.1,'Variazione relativa: '+f(v['percentuale'])+r'\%',w=5.8,size=13)+n(3.7,5.6,'Denominatore: media del periodo iniziale',w=6.5,size=11.5)),richiamo='Una percentuale mantiene significato soltanto se il suo denominatore resta esplicito.',origine='P03:11,22')
p('L’intervallo classico come riferimento condizionato',
'''L’intervallo t della regressione utilizza una varianza residua comune e novantotto gradi di libertà. La sua interpretazione esatta richiede errori indipendenti, gaussiani e con varianza costante, oltre a una media correttamente specificata. L’indipendenza va esaminata attraverso l’ordine delle osservazioni. Il progetto conserva questo intervallo come riferimento esplicito, rispetto al quale valutare l’effetto di una diversa stima della covarianza, mantenendo invariata la stima del contrasto.''',formula=r'\widehat{\mathrm{Var}}_{iid}(\widehat\beta)=s^2\left(\frac1{27}+\frac1{73}\right)\\IC_{iid}=\widehat\beta\pm t_{0{,}975;98}\,SE_{iid}',destra='La parola indipendente riguarda una proprietà congiunta degli errori annuali. La presenza di cento righe non garantisce cento contributi informativi equivalenti a quelli di un campione indipendente, anche quando la distribuzione marginale appare regolare.',richiamo='Il riferimento classico va letto attraverso le ipotesi che giustificano il suo errore standard.',origine='P03:12')
p('I residui vengono riportati agli anni',
'''Sottraendo a ogni anno la media del proprio periodo si ottengono i residui del modello. La loro rappresentazione temporale permette di riconoscere sequenze persistenti, episodi estremi e possibili variazioni del livello rimaste nella specificazione. La somma dei residui entro ciascun periodo è nulla per costruzione, mentre l’assenza di dipendenza seriale costituisce una proprietà diversa. La diagnosi interpreta quindi ciò che la regressione lascia nella sequenza, evitando di attribuire al semplice centramento una giustificazione dell’indipendenza.''',figura='P03/F03',didascalia='Residui del modello a due livelli, ordinati per anno. Il riferimento orizzontale corrisponde allo scostamento nullo.',richiamo='Le proprietà algebriche dei residui devono essere distinte dalle ipotesi sul processo temporale.',origine='P03:13')
p('L’ACF descrive la memoria residua',
'''L’autocorrelazione confronta residui separati da uno o più anni e riassume la persistenza lineare alle diverse distanze temporali. Le bande tratteggiate indicano il riferimento approssimativo di rumore bianco, calcolato come più o meno 1,96 diviso la radice di cento. Ogni banda riguarda una singola correlazione e non fornisce una verifica simultanea delle quindici barre. La lettura considera anche il disegno complessivo delle correlazioni e la possibilità che una struttura della media ancora omessa produca persistenza apparente.''',formula=r'\widehat\rho(h)=\frac{\sum_{t=h+1}^{n}\widehat e_t\widehat e_{t-h}}{\sum_{t=1}^{n}\widehat e_t^2}',figura='P03/F04',didascalia='ACF dei residui fino a quindici anni. Bande puntuali approssimative, prive di correzione per confronti multipli.',richiamo='L’ACF sostiene una diagnosi della dipendenza e richiede una lettura coerente con il modello della media.',origine='P03:14')
m.sezione_nuova('Covarianza HAC e analisi di sensibilità')
p('La dipendenza entra nella covarianza delle somme',
'''Quando gli errori sono correlati, la varianza di una somma comprende anche le covarianze fra termini distinti. La matrice HAC applica questo principio ai contributi della regressione, conservando i prodotti fra residui e righe della matrice del modello a diversi ritardi. La stima OLS resta invariata, mentre cambia la covarianza che ne descrive l’incertezza. La costruzione richiede condizioni di dipendenza debole e un modello della media adeguato; il suo carattere asintotico deve rimanere esplicito anche con cento osservazioni.''',formula=r'\mathrm{Var}\!\left(\sum_t Z_t\right)=\sum_t\mathrm{Var}(Z_t)+2\sum_{s<t}\mathrm{Cov}(Z_s,Z_t)',tikz=d('D04',''.join(rect(.7+j*.75,.8+i*.7,1.4+j*.75,1.45+i*.7,'Quantum' if abs(i-j)<=1 else 'Rule') for i in range(6) for j in range(6))+n(3.7,.45,'Covarianze fra contributi temporali',w=6.5,size=11.5)+n(3.7,6,'Diagonale: varianze; bande: ritardi vicini.',w=6.7,size=11)),richiamo='La dipendenza modifica l’informazione contenuta nella somma attraverso le covarianze fra osservazioni.',origine='P03:15')
p('Pesi di Bartlett e ritardo massimo dichiarato',
'''Si indicano con u i prodotti fra la riga del modello e il residuo corrispondente. La matrice interna della covarianza somma i prodotti contemporanei e quelli ritardati, assegnando a questi ultimi pesi di Bartlett decrescenti. Il progetto fissa inizialmente un ritardo massimo di tre anni, senza prewhitening. La figura confronta i pesi per tre e dieci anni, rendendo visibile come la scelta determini quali associazioni residue entrino nel calcolo e con quale contributo.''',formula=r'u_t=x_t\widehat e_t,\quad G_h=\sum_{t=h+1}^{n}u_tu_{t-h}^{T}\\S_L=G_0+\sum_{h=1}^{L}\left(1-\frac{h}{L+1}\right)(G_h+G_h^T)',figura='P03/F08',didascalia='Pesi di Bartlett per due ritardi massimi. Il peso contemporaneo è uno; oltre L i contributi sono esclusi.',richiamo='Il ritardo massimo è una scelta del protocollo, della quale viene esaminata la sensibilità.',origine='P03:15–16')
p('Dalla matrice interna all’intervallo asintotico',
'''La matrice interna viene trasformata mediante l’inversa di X trasposta X e moltiplicata per il fattore cento diviso novantotto. Questa convenzione corrisponde alla correzione finita n diviso n meno k, con due coefficienti stimati. L’errore standard della differenza è la radice dell’elemento diagonale corrispondente alla pendenza. L’intervallo adotta il quantile normale 1,96 e rimane asintotico: la correzione finita non lo trasforma in un intervallo esatto per una serie di lunghezza limitata.''',formula=r'\widehat V_{HAC}=\frac{n}{n-k}(X^TX)^{-1}S_L(X^TX)^{-1}\\IC_{HAC}=\widehat\beta\pm1{,}96\sqrt{[\widehat V_{HAC}]_{22}}',destra='R/covarianze.R contiene l’implementazione leggibile della matrice, condivisa con il progetto sulla CO₂. Le verifiche controllano simmetria, positività nel caso studiato e corrispondenza numerica con una seconda implementazione.',richiamo='Formula, correzione finita, ritardo e distribuzione di riferimento devono essere riportati insieme.',fonti='Newey–West; documentazione statsmodels, cov_hac',origine='P03:15–18')
c=estratto('P03','HAC',"source('R/covarianze.R')\nd <- read.csv('dati/progetti/nile.csv')\nd$post <- as.integer(d$year>=1898)\nf <- lm(volume_1e8_m3~post,d)\nV <- hac_cov(model.matrix(f),resid(f),3)\nintervallo(coef(f)[2],sqrt(V[2,2]))")
p('Il calcolo mantiene separati stima e incertezza',
f'''Il frammento stima il modello una sola volta e passa matrice del disegno e residui alla funzione HAC. Il contrasto rimane {f(v['beta'])}, mentre l’errore standard HAC è circa {f(v['se_HAC'])}. L’intervallo normale corrispondente si estende da {f(v['IC_HAC'][0])} a {f(v['IC_HAC'][1])}, nella scala dei volumi annuali. La separazione fra adattamento e covarianza rende controllabile quale componente dell’analisi sia stata modificata e impedisce di confondere una maggiore precisione numerica con un cambiamento della stima.''',codice=c,richiamo='La variante della covarianza cambia l’incertezza attribuita al medesimo contrasto OLS.',origine='P03:16–18,25')
p('Intervalli riferiti alla stessa differenza',
'''Le due costruzioni vengono rappresentate sulla stessa scala e condividono la stima centrale. La loro diversa ampiezza dipende dalle ipotesi sulla struttura degli errori e dalla formula di covarianza. Un intervallo HAC può essere più ampio o più stretto di quello classico, poiché il risultato dipende da segno e intensità delle covarianze stimate. L’argomento si concentra sulla stabilità della conclusione entro le specificazioni dichiarate, mantenendo distinta questa sensibilità dall’incertezza relativa alla scelta storica della soglia.''',figura='P03/F05',didascalia='Intervallo t i.i.d. e intervallo normale HAC con L = 3. Unità: centinaia di milioni di metri cubi.',richiamo='La robustezza a una specificazione riguarda le varianti effettivamente esaminate.',origine='P03:17–18')
p('Sensibilità alla memoria inclusa nel calcolo',
'''La griglia dei ritardi massimi comprende zero, uno, tre, cinque e dieci anni. Ogni variante mantiene gli stessi dati e lo stesso modello della media, modificando soltanto la quantità di dipendenza residua inclusa nella covarianza. Il caso zero conserva una correzione per eteroschedasticità e omette i prodotti ritardati; gli altri casi aggiungono contributi pesati. Presentare l’intera griglia permette di discutere l’incertezza senza selezionare a posteriori il ritardo che favorisca una conclusione desiderata.''',figura='P03/F06',didascalia='Stima OLS comune e intervalli HAC su una griglia dichiarata di ritardi massimi.',richiamo='L’analisi di sensibilità documenta le conseguenze delle scelte mantenendo visibili tutte le varianti.',origine='P03:19')
p('Sensibilità alla collocazione della separazione',
'''Spostando la soglia dal 1896 al 1900 si modifica l’assegnazione di pochi anni e si ricalcola la differenza fra medie. La figura descrive quanto il contrasto dipenda dalla collocazione precisa del confine entro questo intervallo storico. Le cinque stime utilizzano quasi tutti gli stessi dati e non costituiscono cinque conferme indipendenti. Un’analisi che cercasse automaticamente il punto di cambiamento richiederebbe un’inferenza capace di rappresentare la selezione della soglia e la sua incertezza.''',figura='P03/F07',didascalia='Differenza fra periodi per cinque soglie vicine. Confronto descrittivo, distinto da una ricerca inferenziale della rottura.',richiamo='La ricerca della soglia e la stima condizionata a una soglia sono problemi inferenziali differenti.',origine='P03:20,29')
m.sezione_nuova('Interpretazione idrologica e consegna')
p('La successione temporale lascia aperta la causa',
'''Il contrasto quantifica una differenza della serie e non identifica l’effetto di una specifica opera idraulica o forzante climatica. Per un’attribuzione occorrerebbero cronologie degli interventi, precipitazioni, informazioni sul bacino e metadati strumentali, oltre a una strategia che distingua spiegazioni concorrenti. La covarianza HAC riguarda l’incertezza del coefficiente sotto il modello e non sostituisce tali informazioni. La relazione conserva pertanto la conclusione descrittiva e formula le osservazioni aggiuntive necessarie a sostenere un’interpretazione fisica più specifica.''',tikz=d('D05',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Differenza osservata fra periodi',w=6)+a(2,2.1,2,3)+a(5.4,2.1,5.4,3,'Quantum')+rect(.4,3.2,3.5,4.7)+n(1.95,3.95,'Forzanti e interventi',w=2.7,size=11.5)+rect(3.9,3.2,7,4.7,'Quantum')+n(5.45,3.95,'Misura e copertura',w=2.7,size=11.5)+n(3.7,5.6,'Confronto delle spiegazioni mediante dati ulteriori',w=6.7,size=11.5)),richiamo='L’attribuzione causale richiede un disegno e informazioni che il solo contrasto temporale non fornisce.',origine='P03:21,23–24')
p('Consegna: sostenere il contrasto e i suoi limiti',
'''La relazione include serie storica, distribuzioni per periodo, contrasto con unità, residui, ACF e confronto degli intervalli. L’esercizio richiede di spiegare perché la stima rimanga invariata passando alla covarianza HAC, mentre la sua precisione cambi. Una risposta completa richiama la presenza dei prodotti ritardati nella varianza e mantiene esplicite le ipotesi asintotiche. Un secondo esercizio esamina l’effetto di una soglia scelta dopo aver osservato la serie, distinguendo questa selezione dalla sensibilità condizionata alle soglie dichiarate.''',destra='R/P03_figure.R produce figure, tabelle e risultati a partire da dati/progetti/nile.csv. La formulazione raccorda regressione, dipendenza temporale e inferenza sviluppate nei moduli M05, M07 e M09. La lettura della documentazione della fonte accompagna l’interpretazione delle unità e della soglia storica.',richiamo='La conclusione collega grandezza, incertezza, origine della soglia e limiti dell’attribuzione.',fonti='R datasets: Nile; statsmodels, cov_hac',origine='P03:25–30')
m.salva()
